import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The drafter's marker for a decision only a human can make; it must be resolved before a PASS. */
const NEEDS_HUMAN_INPUT = /NEEDS HUMAN INPUT/;
/** A bolded field label at the start of a bullet: `- **Retention**: 30 days` or `- **Retention:** 30 days`. */
const FIELD_LINE = /^(\s*)[-*]\s*\*\*([^*]+)\*\*(.*)$/;

interface Section {
  heading: string;
  body: string;
}

interface Field {
  label: string;
  /** Index of the field's line within the subsection body. */
  line: number;
  /** The answer: text on the field line plus any indented lines below it. */
  value: string;
  /** True when neither the field line nor anything indented below it answers the field. */
  empty: boolean;
}

function indentOf(line: string): number {
  return line.match(/^\s*/)?.[0].length ?? 0;
}

/** Returns the text after the colon that ends a field label, skipping colons inside "( … )" hints. */
function afterLabelColon(rest: string): string | null {
  let depth = 0;
  for (let i = 0; i < rest.length; i += 1) {
    if (rest[i] === '(') depth += 1;
    else if (rest[i] === ')') depth = Math.max(0, depth - 1);
    else if (rest[i] === ':' && depth === 0) return rest.slice(i + 1);
  }
  return null;
}

/** Parses the bold-labelled fields of a subsection body, resolving answers that sit on indented lines below. */
function parseFields(lines: string[]): Field[] {
  const parsed = lines.map((line) => {
    const m = line.match(FIELD_LINE);
    if (!m) return null;
    const [, indent, bold, rest] = m;
    // Colon inside the bold (`**Tier:**`) or after it (`**Tier**:`, `**Tier** (hint):`).
    const inline = bold.endsWith(':')
      ? rest
      : (afterLabelColon(rest) ?? (rest.trimEnd().endsWith(':') ? '' : rest));
    return {
      label: bold.replace(/:$/, '').trim(),
      indent: indent.length,
      inline: inline.trim()
    };
  });

  const fields: Field[] = [];
  lines.forEach((line, i) => {
    const field = parsed[i];
    if (!field) return;
    const below: number[] = [];
    for (let j = i + 1; j < lines.length; j += 1) {
      if (!lines[j].trim()) continue;
      if (indentOf(lines[j]) <= field.indent) break;
      below.push(j);
    }
    // Lines below that are themselves unanswered fields (e.g. nested `- **Sub**:`) do not answer this one.
    const empty =
      !field.inline &&
      below.every((j) => {
        const other = parsed[j];
        return other !== null && !other.inline;
      });
    const value = below.reduce(
      (acc, j) => `${acc} ${lines[j].trim()}`,
      field.inline
    );
    fields.push({ label: field.label, line: i, value: empty ? '' : value.trim(), empty });
  });
  return fields;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string, fields: Field[]): RiskTier | null {
  // When an explicit "Tier" field exists, its answer is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const tierField = fields.find((f) => /^tier\b/i.test(f.label));
  const plainLine = body.split(/\r?\n/).find((l) => /^\s*[-*]\s*tier\b/i.test(l));
  const haystacks = [tierField ? tierField.value : plainLine ?? body];
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

/** The subsection body without its unanswered field lines. */
function answeredText(lines: string[], fields: Field[]): string {
  const emptyLines = new Set(fields.filter((f) => f.empty).map((f) => f.line));
  return lines
    .filter((_, i) => !emptyLines.has(i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const lines = body.split(/\r?\n/);
    const fields = parseFields(lines);
    const answered = answeredText(lines, fields);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = body.split(/\r?\n/).filter((l) => EMPTY_FIELD.test(l));
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

