    const lines = body.split(/\r?\n/);
    const fields = parseFields(lines);
    const answered = answeredText(lines, fields);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    for (const field of fields.filter((f) => f.empty)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${lines[field.line].trim()}`,
        source: 'validator'
      });
    }
    for (const line of lines.filter((l) => NEEDS_HUMAN_INPUT.test(l))) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unresolved NEEDS HUMAN INPUT in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body, fields);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
